import{_ as s,o as e,c as o,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const b=JSON.parse('{"title":"Assets do VLibras","description":"","frontmatter":{},"headers":[],"relativePath":"vlibras-setup.md","filePath":"vlibras-setup.md"}'),t={name:"vlibras-setup.md"};function r(n,a,l,d,c,p){return e(),o("div",null,[...a[0]||(a[0]=[i(`<h1 id="assets-do-vlibras" tabindex="-1">Assets do VLibras <a class="header-anchor" href="#assets-do-vlibras" aria-label="Permalink to &quot;Assets do VLibras&quot;">​</a></h1><p>O player do VLibras <strong>não é um pacote npm</strong>: é um bundle Unity/WebGL (avatar Ícaro) que expõe <code>window.VLibras.Player</code> e baixa os assets Unity de um diretório estático.</p><p>Por serem arquivos grandes (~13 MB, incluindo <code>.wasm</code> e <code>.data</code>), eles <strong>não são versionados no git</strong> (ver <code>.gitignore</code> → <code>public/vlibras/</code>).</p><h2 id="padrao-assets-unity-via-cdn-nao-precisa-dos-13-mb-locais" tabindex="-1">Padrão: assets Unity via CDN (não precisa dos 13 MB locais) <a class="header-anchor" href="#padrao-assets-unity-via-cdn-nao-precisa-dos-13-mb-locais" aria-label="Permalink to &quot;Padrão: assets Unity via CDN (não precisa dos 13 MB locais)&quot;">​</a></h2><p>Por padrão, o loader busca os assets Unity (<code>target/</code>) direto do <strong>CDN oficial</strong> (jsDelivr), então <strong>não é preciso ter a pasta <code>target/</code> localmente</strong> para o avatar funcionar num PC recém-clonado. O default está em <code>vlibras-loader.ts</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cdn.jsdelivr.net/gh/spbgovbr-vlibras/vlibras-portal@&lt;sha&gt;/app/target</span></span></code></pre></div><ul><li>Fixado num <strong>commit SHA</strong> (não na branch <code>@sgd</code>) para não quebrar se a branch mudar. Para atualizar, pegue o novo SHA em <a href="https://github.com/spbgovbr-vlibras/vlibras-portal" target="_blank" rel="noreferrer">https://github.com/spbgovbr-vlibras/vlibras-portal</a> e troque em <code>vlibras-loader.ts</code>.</li><li>O CDN responde <code>200</code> com <code>Access-Control-Allow-Origin: *</code>, então funciona cross-origin (o Unity baixa os <code>.unityweb</code> via XHR).</li><li><strong>Requer internet em runtime.</strong> Para ambiente offline, use os arquivos locais (seção abaixo) passando <code>targetPath: &#39;/vlibras/target&#39;</code> nas opções do plugin.</li></ul><blockquote><p>O bundle <code>vlibras.js</code> (~47 KB) <strong>continua sendo carregado localmente</strong> de <code>/vlibras/vlibras.js</code>; só os assets Unity pesados vêm do CDN.</p></blockquote><h2 id="assets-locais-fallback-offline" tabindex="-1">Assets locais (fallback / offline) <a class="header-anchor" href="#assets-locais-fallback-offline" aria-label="Permalink to &quot;Assets locais (fallback / offline)&quot;">​</a></h2><p>A pasta <code>public/vlibras/</code> deste projeto já traz os arquivos e serve como fallback offline. Para forçar o uso local, passe <code>targetPath: &#39;/vlibras/target&#39;</code> (e, se quiser, <code>bundleUrl: &#39;/vlibras/vlibras.js&#39;</code>) nas opções do plugin <code>vlibras</code>.</p><p>Se você clonar o projeto <strong>sem</strong> essa pasta e quiser rodar offline, reconstrua-a com a estrutura abaixo.</p><h3 id="o-que-precisa-existir" tabindex="-1">O que precisa existir <a class="header-anchor" href="#o-que-precisa-existir" aria-label="Permalink to &quot;O que precisa existir&quot;">​</a></h3><p>O loader usa, localmente:</p><ul><li>o bundle em <code>/vlibras/vlibras.js</code> (define <code>window.VLibras</code>)</li><li>os assets Unity em <code>/vlibras/target/</code></li></ul><p>Ou seja, a estrutura final em <code>public/</code> deve ser:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public/vlibras/</span></span>
<span class="line"><span>├── vlibras.js                              # bundle do player (~47 KB)</span></span>
<span class="line"><span>└── target/</span></span>
<span class="line"><span>    ├── UnityLoader.js                      # loader do Unity (~156 KB)</span></span>
<span class="line"><span>    ├── playerweb.json                      # manifesto do build WebGL</span></span>
<span class="line"><span>    ├── playerweb.data.unityweb             # dados/assets do avatar (~10 MB)</span></span>
<span class="line"><span>    ├── playerweb.wasm.code.unityweb        # código WASM (~3 MB)</span></span>
<span class="line"><span>    └── playerweb.wasm.framework.unityweb   # framework WASM (~76 KB)</span></span></code></pre></div><h2 id="de-onde-vem" tabindex="-1">De onde vêm <a class="header-anchor" href="#de-onde-vem" aria-label="Permalink to &quot;De onde vêm&quot;">​</a></h2><p>O bundle é o player oficial open-source do governo federal:</p><ul><li><strong>Repositório:</strong> <a href="https://github.com/spbgovbr-vlibras/vlibras-player-webjs" target="_blank" rel="noreferrer">https://github.com/spbgovbr-vlibras/vlibras-player-webjs</a></li><li><strong>Licença:</strong> LGPLv3</li><li><strong>Versão dos assets embutida neste projeto:</strong> <code>2018.3.1 / WEBGL</code></li></ul><p>O <code>vlibras.js</code> aponta internamente para os serviços oficiais:</p><ul><li><code>https://dicionario2.vlibras.gov.br/...</code> — dicionário de sinais</li><li><code>https://traducao2.vlibras.gov.br/translate</code> — serviço de tradução</li></ul><h2 id="reconstruir-a-pasta-local-so-se-precisar-de-offline" tabindex="-1">Reconstruir a pasta local (só se precisar de offline) <a class="header-anchor" href="#reconstruir-a-pasta-local-so-se-precisar-de-offline" aria-label="Permalink to &quot;Reconstruir a pasta local (só se precisar de offline)&quot;">​</a></h2><p>Com o CDN como padrão, você <strong>não precisa</strong> disto para rodar online — só se quiser o fallback offline. Escolha <strong>uma</strong> das opções.</p><h3 id="opcao-a-—-copiar-de-um-clone-que-ja-funciona-mais-rapido" tabindex="-1">Opção A — copiar de um clone que já funciona (mais rápido) <a class="header-anchor" href="#opcao-a-—-copiar-de-um-clone-que-ja-funciona-mais-rapido" aria-label="Permalink to &quot;Opção A — copiar de um clone que já funciona (mais rápido)&quot;">​</a></h3><p>Se você já tem o projeto rodando em outra máquina, copie a pasta inteira:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># no PC que já tem os assets, a partir da raiz do projeto:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> czf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vlibras-assets.tar.gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public/vlibras</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># transfira o vlibras-assets.tar.gz (pen drive, scp, etc.) e no PC novo:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vlibras-assets.tar.gz</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # recria public/vlibras/</span></span></code></pre></div><p>Ou via <code>scp</code> direto entre as máquinas:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usuario@pc-antigo:/caminho/do/projeto/public/vlibras</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./public/</span></span></code></pre></div><h3 id="opcao-b-—-obter-do-projeto-oficial" tabindex="-1">Opção B — obter do projeto oficial <a class="header-anchor" href="#opcao-b-—-obter-do-projeto-oficial" aria-label="Permalink to &quot;Opção B — obter do projeto oficial&quot;">​</a></h3><ol><li>Clone o player oficial:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/spbgovbr-vlibras/vlibras-player-webjs</span></span></code></pre></div></li><li>Gere/baixe o bundle e os assets Unity conforme as instruções do README de lá (build WebGL <code>2018.3.1</code>).</li><li>Copie os arquivos para dentro de <code>public/vlibras/</code> seguindo a estrutura da seção <strong>&quot;O que precisa existir&quot;</strong> acima.</li></ol><h2 id="verificar-se-ficou-correto" tabindex="-1">Verificar se ficou correto <a class="header-anchor" href="#verificar-se-ficou-correto" aria-label="Permalink to &quot;Verificar se ficou correto&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>O avatar Ícaro deve aparecer. Se houver erro, abra o DevTools (aba Network) e confira os <code>200</code>:</p><ul><li><strong>Padrão (CDN):</strong> <code>/vlibras/vlibras.js</code> local + <code>.../vlibras-portal@&lt;sha&gt;/app/target/playerweb.json</code> no <code>cdn.jsdelivr.net</code>.</li><li><strong>Modo local:</strong> <code>/vlibras/vlibras.js</code> e <code>/vlibras/target/playerweb.json</code>. Se algum der <code>404</code>, a pasta <code>public/vlibras/target/</code> não existe — reconstrua-a (seção acima).</li></ul><h2 id="hospedando-em-outro-caminho" tabindex="-1">Hospedando em outro caminho <a class="header-anchor" href="#hospedando-em-outro-caminho" aria-label="Permalink to &quot;Hospedando em outro caminho&quot;">​</a></h2><p>Se preferir servir os assets de outro lugar (CDN, subpasta), passe <code>bundleUrl</code> e <code>targetPath</code> nas opções do plugin <code>vlibras</code> — ver a tabela de configuração na <a href="/api.html">Referência da API</a>.</p><h2 id="por-que-o-avatar-soletrava-tudo-e-a-correcao" tabindex="-1">Por que o avatar soletrava tudo (e a correção) <a class="header-anchor" href="#por-que-o-avatar-soletrava-tudo-e-a-correcao" aria-label="Permalink to &quot;Por que o avatar soletrava tudo (e a correção)&quot;">​</a></h2><p>O <code>player.translate(texto)</code> do VLibras trabalha em <strong>duas etapas</strong>, ambas via HTTP:</p><ol><li><strong>Texto → glosa</strong> (<code>traducao2.vlibras.gov.br/translate</code>): converte o português em <strong>glosa de Libras</strong> (ex.: <code>eu estou com dor de cabeça</code> → <code>EU DOR&amp;CABEÇA</code>).</li><li><strong>Glosa → animação</strong> (<code>dicionario2.vlibras.gov.br/...</code>): para cada palavra da glosa, baixa o <strong>AssetBundle Unity do sinal</strong> e anima.</li></ol><p>Se <strong>qualquer</strong> etapa falha no browser, o player cai no fallback <code>play(texto.toUpperCase())</code> e o avatar <strong>SOLETRA letra a letra (datilologia)</strong>.</p><p><strong>A causa raiz:</strong> o bundle vinha apontando para os hosts <strong>legados <code>-dth</code></strong>, que estão quebrados de dois jeitos:</p><table tabindex="0"><thead><tr><th>Etapa</th><th>Host <code>-dth</code> (antigo)</th><th>Host sem <code>-dth</code> (atual)</th></tr></thead><tbody><tr><td>Tradução</td><td><code>traducao2-dth.../dl/translate</code> → <strong>401</strong> (exige auth)</td><td><code>traducao2.vlibras.gov.br/translate</code> → <strong>200 + CORS</strong></td></tr><tr><td>Dicionário</td><td><code>dicionario2-dth...</code> → 200 mas <strong>sem header CORS</strong> (browser bloqueia)</td><td><code>dicionario2.vlibras.gov.br/...</code> → <strong>200 + CORS</strong></td></tr></tbody></table><p>A correção é simplesmente usar os <strong>hosts novos (sem <code>-dth</code>)</strong>, que são públicos, sem autenticação e com <code>Access-Control-Allow-Origin</code> — funcionam direto do browser, sem proxy. Onde ficam:</p><ul><li><strong>Dicionário de sinais:</strong> URLs dentro do próprio bundle <code>public/vlibras/vlibras.js</code> (<code>dictionaryUrl</code> / <code>dictionaryStaticUrl</code>).</li><li><strong>Tradutor:</strong> default em <code>vlibras-loader.ts</code> (<code>DEFAULT_TRANSLATOR_URL</code>), passado ao <code>Player({ translator })</code>. Sobrescreva com <code>vlibras=&amp;#123;&amp;#123; translatorUrl: &#39;...&#39; &amp;#125;&amp;#125;</code>.</li></ul><blockquote><p>Depois de trocar os hosts, faça <strong>hard reload</strong> (Cmd+Shift+R): o browser mantém o <code>vlibras.js</code> antigo em cache e continua batendo nos hosts <code>-dth</code>.</p></blockquote><p>Teste rápido dos endpoints públicos:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -XPOST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://traducao2.vlibras.gov.br/translate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;content-type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;text&quot;:&quot;eu estou com dor de cabeça&quot;}&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # -&gt; EU DOR&amp;CABEÇA</span></span></code></pre></div><h2 id="opcional-self-hosting-do-tradutor" tabindex="-1">(Opcional) Self-hosting do tradutor <a class="header-anchor" href="#opcional-self-hosting-do-tradutor" aria-label="Permalink to &quot;(Opcional) Self-hosting do tradutor&quot;">​</a></h2><p>Só é necessário se você quiser rodar <strong>offline</strong> ou independente do gov.br. O <code>docker-compose.translator.yml</code> sobe o tradutor oficial (<code>translator-api</code> 2.1.4 + <code>text-core</code> + RabbitMQ + Redis + MongoDB), expondo <code>POST /translate</code> em <code>:3000</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.translator.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Para o app usar: passe <code>vlibras=&amp;#123;&amp;#123; translatorUrl: &#39;/vlibras-translate&#39; &amp;#125;&amp;#125;</code> e adicione um proxy same-origin no Vite (<code>/vlibras-translate</code> → <code>http://localhost:3000/translate</code>). Notas: as imagens do VLibras são amd64-only (o compose força <code>platform: linux/amd64</code>, rodam via emulação em Apple Silicon); use <code>ENABLE_DL_TRANSLATION=false</code> (por regras) — o modo neural falha sob emulação amd64.</p>`,51)])])}const u=s(t,[["render",r]]);export{b as __pageData,u as default};
